const incoming = $input.first()?.json || {};

const fallback = {
  pipeline_status: "ready_for_rendering",
  selected_title: "Why Stars Glow in Different Colors",
  selected_pillar: "chemistry_of_space",
  research_brief: {
    topic: "Why stars glow in different colors",
    core_question: "Why do stars have different visible colors?",
    one_sentence_answer: "A star's surface temperature strongly affects the spectrum and apparent color of the light it emits.",
    key_points: [
      "Stars emit broad thermal spectra.",
      "Hotter stars have relatively more short-wavelength visible light.",
      "Cooler stars have relatively more long-wavelength visible light."
    ],
    research_queries: [
      "stellar color effective temperature blackbody spectrum"
    ]
  },
  script_package: {
    title: "Why Stars Glow in Different Colors",
    script: "Stars can look blue, white, yellow, orange, or red because their surface temperatures change the spectrum of light they emit. Hotter stars produce relatively more short-wavelength visible light, so they can appear blue-white. Cooler stars produce relatively more long-wavelength visible light and can appear orange or red. A star is not emitting just one color, though. It produces a broad spectrum, and temperature shifts the balance across that spectrum. So when astronomers measure a star's color and spectrum, they can learn about its temperature from light that traveled across space to reach us.",
    actual_word_count: 88
  },
  storyboard: {
    format: "9:16",
    target_duration_seconds: 45,
    scenes: [
      {"scene_number":1,"start_sec":0,"end_sec":4,"voice_line":"Stars can look blue, white, yellow, orange, or red.","visual_type":"astronomy_image","visual_instruction":"Show a field of stars with visibly different colors.","caption":"WHY DIFFERENT COLORS?","asset_query":"colorful stars star field"},
      {"scene_number":2,"start_sec":4,"end_sec":9,"voice_line":"Their surface temperatures change the spectrum of light they emit.","visual_type":"spectrum","visual_instruction":"Show a broad visible spectrum shifting with temperature.","caption":"TEMPERATURE CHANGES THE SPECTRUM","asset_query":""},
      {"scene_number":3,"start_sec":9,"end_sec":15,"voice_line":"Hotter stars produce relatively more short-wavelength visible light.","visual_type":"diagram","visual_instruction":"Compare a hotter star to a cooler star and point toward shorter wavelengths.","caption":"HOTTER → BLUER","asset_query":""},
      {"scene_number":4,"start_sec":15,"end_sec":21,"voice_line":"Cooler stars produce relatively more long-wavelength visible light.","visual_type":"diagram","visual_instruction":"Compare a cooler star and emphasize longer visible wavelengths.","caption":"COOLER → REDDER","asset_query":""},
      {"scene_number":5,"start_sec":21,"end_sec":28,"voice_line":"A star is not emitting just one color, though.","visual_type":"spectrum","visual_instruction":"Show a continuous broad spectrum rather than a single line.","caption":"NOT JUST ONE COLOR","asset_query":""},
      {"scene_number":6,"start_sec":28,"end_sec":36,"voice_line":"It produces a broad spectrum, and temperature shifts the balance across that spectrum.","visual_type":"chart","visual_instruction":"Show two simplified broad spectral curves with different peaks.","caption":"THE WHOLE SPECTRUM SHIFTS","asset_query":""},
      {"scene_number":7,"start_sec":36,"end_sec":45,"voice_line":"Astronomers use that light to learn about a star's temperature from across space.","visual_type":"astronomy_image","visual_instruction":"Show a telescope receiving starlight and a spectrum graphic.","caption":"READING TEMPERATURE FROM LIGHT","asset_query":"telescope star spectrum astronomy"}
    ]
  },
  renderer_handoff: {}
};

const src = incoming.pipeline_status ? incoming : fallback;

const query =
  src.research_brief?.research_queries?.[0] ||
  src.research_brief?.core_question ||
  src.selected_title ||
  fallback.selected_title;

return [{
  json: {
    ...src,
    external_research_query: query,
    github_owner: "REPLACE_WITH_YOUR_GITHUB_USERNAME",
    github_repo: "science-shorts-renderer",
    renderer_event_type: "render_science_short"
  }
}];

const response = $json;
const prior = $('Normalize Stage 02 Package').item.json;

function rebuildAbstract(index) {
  if (!index || typeof index !== 'object') return '';
  const words = [];
  for (const [word, positions] of Object.entries(index)) {
    for (const p of positions || []) words.push([Number(p), word]);
  }
  words.sort((a,b) => a[0]-b[0]);
  return words.map(x => x[1]).join(' ');
}

const papers = (response.results || []).slice(0,5).map(w => ({
  id: w.id || '',
  doi: w.doi || '',
  title: w.title || '',
  publication_year: w.publication_year || null,
  cited_by_count: w.cited_by_count || 0,
  source:
    w.primary_location?.source?.display_name ||
    w.primary_location?.landing_page_url ||
    '',
  authors: (w.authorships || []).slice(0,4).map(a => a.author?.display_name).filter(Boolean),
  abstract: rebuildAbstract(w.abstract_inverted_index).slice(0,5000)
}));

return [{
  json: {
    ...prior,
    openalex_papers: papers,
    openalex_result_count: papers.length
  }
}];

function parse(value, depth=0) {
  if (depth > 10 || value == null) return null;
  if (typeof value === 'object') {
    if (value.status && (value.confidence !== undefined)) return value;
    for (const v of Object.values(value)) {
      const x = parse(v, depth+1);
      if (x) return x;
    }
  }
  if (typeof value === 'string') {
    let s = value.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'').trim();
    try { return JSON.parse(s); } catch {}
    const a=s.indexOf('{'), b=s.lastIndexOf('}');
    if (a>=0 && b>a) { try { return JSON.parse(s.slice(a,b+1)); } catch {} }
  }
  return null;
}

const v = parse($json);
if (!v) throw new Error('Could not parse external verification JSON.');

const prior = $('Extract Scholarly Evidence').item.json;
const passed =
  String(v.status || '').toLowerCase() === 'verified' &&
  Number(v.confidence || 0) >= 0.75 &&
  (v.unsupported_or_conflicting_claims || []).length === 0;

return [{
  json: {
    ...prior,
    external_verification: v,
    external_verification_passed: passed
  }
}];

return [{
  json: {
    pipeline_status: "needs_external_review",
    selected_title: $json.selected_title,
    external_verification: $json.external_verification,
    scholarly_results: $json.openalex_papers,
    next_action: "Do not render yet. Review or revise the flagged/unsupported claims."
  }
}];

const src = $json;
const jobId = `${Date.now()}-${Math.random().toString(36).slice(2,8)}`;

const scenes =
  src.renderer_handoff?.scenes ||
  src.storyboard?.scenes ||
  [];

const narration =
  src.renderer_handoff?.narration ||
  src.script_package?.script ||
  '';

const payload = {
  job_id: jobId,
  title: src.renderer_handoff?.title || src.script_package?.title || src.selected_title,
  narration,
  scenes,
  verified_sources: (src.external_verification?.source_ids_used || []).slice(0,8),
  aspect_ratio: "9:16",
  target_duration_seconds:
    Number(src.renderer_handoff?.target_duration_seconds || src.storyboard?.target_duration_seconds || 45)
};

const body = {
  event_type: src.renderer_event_type || "render_science_short",
  client_payload: payload
};

return [{
  json: {
    ...src,
    render_job_id: jobId,
    artifact_name: `science-short-${jobId}`,
    renderer_payload: payload,
    github_dispatch_body: body
  }
}];

const response = $json;
const ctx = $('Restore Render Context').item.json;
const artifact = (response.artifacts || [])[0] || null;

return [{
  json: {
    ...ctx,
    artifact_found: !!artifact,
    artifact: artifact ? {
      id: artifact.id,
      name: artifact.name,
      size_in_bytes: artifact.size_in_bytes,
      archive_download_url: artifact.archive_download_url,
      created_at: artifact.created_at,
      expires_at: artifact.expires_at
    } : null
  }
}];

return [{
  json: {
    pipeline_status: "video_rendered",
    selected_title: $json.selected_title,
    render_job_id: $json.render_job_id,
    artifact_name: $json.artifact_name,
    artifact: $json.artifact,
    note: "The GitHub Actions artifact contains science_short.mp4 plus the render manifest and source metadata."
  }
}];

return [{
  json: {
    pipeline_status: "render_still_running_or_failed",
    selected_title: $json.selected_title,
    render_job_id: $json.render_job_id,
    artifact_name: $json.artifact_name,
    github_owner: $json.github_owner,
    github_repo: $json.github_repo,
    note: "No matching artifact was visible after the wait period. Check the GitHub Actions run. If it is still running, wait and execute the artifact lookup again."
  }
}];
